<?php namespace App\Http\Middleware; use Closure; use Illuminate\Http\Request; class SetActiveTenant{public function handle(Request $request, Closure $next){ if(auth()->check()){ $tenantId=session('active_tenant_id') ?: auth()->user()->active_tenant_id ?: auth()->user()->tenants()->value('tenants.id'); if($tenantId){session(['active_tenant_id'=>$tenantId]); view()->share('activeTenant', auth()->user()->tenants()->where('tenants.id',$tenantId)->first()); view()->share('navTenants', auth()->user()->tenants()->orderBy('name')->get());}} return $next($request);} }
